#[path="support/engine_clone_fixture.rs"]mod fixture;
use fixture::*;
use serde_json::json;
#[test]fn synthetic_fixture_has237_depth20_books_and_native_orders(){let e=warm().unwrap();assert_eq!(e.known_exchanges().len(),237);assert!(!e.order_records().is_empty());assert!(e.fills().is_empty());assert!(e.live_order_bindings().is_empty());assert_eq!(book(0,1,BASE_MS)["book"]["bids"].as_array().unwrap().len(),20);assert_eq!(book(0,1,BASE_MS)["book"]["asks"].as_array().unwrap().len(),20);}
#[test]fn warmed_clones_preserve_public_financial_state_exactly(){let e=warm().unwrap();let before=fingerprint(&e).unwrap();for _ in 0..3{assert_eq!(fingerprint(&e.clone()).unwrap(),before);}assert_eq!(fingerprint(&e).unwrap(),before);}
#[test]fn rejected_partial_gap_mutation_rolls_back_and_future_behavior_matches_fresh_engine(){let mut e=warm().unwrap();let mut independent=warm().unwrap();assert_eq!(fingerprint(&e).unwrap(),fingerprint(&independent).unwrap());let p=rollback_probe(&mut e,WARM_END_MS+1).unwrap();assert_eq!(p["error"],"GAP_SCOPE");let probe=tick(WARM_END_MS+2);e.advance(&probe).unwrap();independent.advance(&probe).unwrap();assert_eq!(fingerprint(&e).unwrap(),fingerprint(&independent).unwrap());}
#[test]fn synthetic_workloads_produce_deterministic_prefixes(){for kind in ["tick","book","gap_and_resync"]{let mut a=warm().unwrap();let mut b=warm().unwrap();for e in workload(kind,8){a.advance(&e).unwrap();b.advance(&e).unwrap();assert_eq!(fingerprint(&a).unwrap(),fingerprint(&b).unwrap());}assert_eq!(rollback_probe(&mut a,WARM_END_MS+10).unwrap()["financialStateUnchanged"],json!(true));}}
